<parameter name="content">import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    console.error("[ErrorBoundary] Caught render error:", error.message);
    console.error("[ErrorBoundary] Component stack:", info.componentStack);
    this.props.onError?.(error, info);
  }

  reset = () => {
    this.setState({ error: null });
  };

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (error) {
      return fallback ? (
        fallback(error, this.reset)
      ) : (
        <DefaultFallback error={error} reset={this.reset} />
      );
    }

    return children;
  }
}

function DefaultFallback({ error, reset }: { error: Error; reset: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.heading}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "center",
    padding: "2rem",
    border: "1px solid #f5c6cb",
    borderRadius: "0.5rem",
    backgroundColor: "#fff5f5",
    color: "#c53030",
    fontFamily: "sans-serif",
    gap: "1rem",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  heading: {
    margin: 0,
    fontSize: "1.25rem",
  },
  message: {
    margin: 0,
    fontSize: "0.875rem",
    whiteSpace: "pre-wrap",
    wordBreak: "break-word",
    color: "#742a2a",
  },
  button: {
    padding: "0.5rem 1.25rem",
    border: "none",
    borderRadius: "0.375rem",
    backgroundColor: "#c53030",
    color: "#fff",
    fontSize: "0.875rem",
    cursor: "pointer",
  },
};
